               '    .partner-carousel .partner:hover{\n'
               '      transform:translateY(-5px) scale(1.02);\n'
               '      box-shadow:0 24px 48px rgba(3,37,92,.20) !important;\n'
               '    }\n'
               '\n'
               '    .partner-carousel .partner img{\n'
               '      max-width:320px !important;\n'
               '      max-height:170px !important;\n'
               '      width:auto !important;\n'
