               '      }\n'
               '\n'
               '      .footer-policy{\n'
               '        justify-self:center;\n'
               '        text-align:center;\n'
               '        font-size:11px;\n'
               '      }\n'
               '\n'
               '      .footer-logos{\n'
               '        justify-self:center;\n'
               '        justify-content:center;\n'
               '        min-width:0;\n'
               '      }\n'
               '\n'
               '      .footer-logo-somos{\n'
               '        height:30px;\n'
               '      }\n'
               '\n'
               '      .footer-logo-coopex{\n'
               '        height:38px;\n'
               '      }\n'
               '\n'
               '      .footer-copy{\n'
               '        justify-self:center;\n'
               '        text-align:center;\n'
               '        white-space:normal;\n'
               '        font-size:12px;\n'
               '      }\n'
               '\n'
               '\n'
               '      .selo-utilidade-box{\n'
               '        align-items:flex-start;\n'
               '        padding:12px;\n'
               '        gap:10px;\n'
               '      }\n'
               '\n'
               '      .selo-utilidade-box img{\n'
               '        width:70px;\n'
               '        height:70px;\n'
               '      }\n'
               '\n'
               '      .selo-utilidade-box strong{\n'
               '        font-size:15px;\n'
               '      }\n'
               '\n'
               '      .selo-utilidade-box p{\n'
               '        font-size:13px;\n'
               '      }\n'
               '\n'
               '      .partner-carousel-area{\n'
               '        grid-template-columns:44px minmax(0,1fr) 44px;\n'
               '        gap:6px;\n'
               '      }\n'
               '\n'
               '      .partner-carousel{\n'
               '        padding:20px 8px !important;\n'
               '      }\n'
               '\n'
               '      .partner-carousel .partner{\n'
               '        flex-basis:260px !important;\n'
               '        width:260px !important;\n'
               '        min-width:260px !important;\n'
               '        min-height:210px !important;\n'
               '        padding:20px !important;\n'
               '      }\n'
               '\n'
               '      .partner-carousel .partner img{\n'
               '        max-width:220px !important;\n'
               '        max-height:120px !important;\n'
               '      }\n'
               '\n'
               '      .partner-carousel .partner span{\n'
               '        font-size:15px !important;\n'
               '      }\n'
               '\n'
               '      .partner-arrow{\n'
