TEMPLATES["admin_card.html"] = _CARD_EDITOR
TEMPLATES["instagram_card.html"] = _CARD_PUBLIC.replace("</head>", _SITE_PUBLIC_GLASS + "<style>\nbody{background:radial-gradient(ellipse at 15% 0%,#78d2ff,transparent 55%),linear-gradient(145deg,var(--primary),#062450)!important}\n.page{width:100%!important;min-height:100dvh!important;padding:clamp(16px,4vw,40px)!important;border-radius:0!important}\n.content{width:100%;max-width:1100px;margin:auto;min-height:calc(100dvh - 80px)!important}\n.name{font-family:system-ui,sans-serif!important;font-weight:850!important}.avatar-wrap{width:{{ card.card_avatar_tamanho|int }}px!important;height:{{ card.card_avatar_tamanho|int }}px!important}\n.links{display:grid!important;grid-template-columns:repeat({{ card.card_colunas|int }},minmax(0,1fr))!important;gap:14px!important}\n.link-btn{min-height:{{ card.card_altura_botao|int }}px!important;border-radius:{{ card.card_raio|int }}px!important;background:linear-gradient(138deg,color-mix(in srgb,var(--btn) {{ card.card_intensidade_vidro|int }}%,transparent),color-mix(in srgb,var(--btn) 78%,var(--primary)))!important;border:1.6px solid #fff!important;box-shadow:0 11px 23px #001b5355,inset 0 3px 4px #ffffffad,inset 0 -3px 5px #145a9f35!important;backdrop-filter:blur(12px)}\n.link-icon{border:1px solid #ffffffa0;border-radius:12px!important;box-shadow:inset 0 1px 4px #ffffff90}\n@media(max-width:680px){.links{grid-template-columns:minmax(0,1fr)!important}}\n</style>" + _SITE_FAVICON + "</head>",1)

