TEMPLATES["instagram_card.html"] = TEMPLATES["instagram_card.html"].replace("</head>", "<style id=\"coopex-card-crystal\">\nhtml body{background:#09284d!important;padding:0!important}\nhtml body .page{background:radial-gradient(ellipse at 12% 0%,#98d4f7 0%,transparent 42%),radial-gradient(ellipse at 100% 36%,#377fb6 0%,transparent 48%),linear-gradient(155deg,#245d92 0%,#123b69 48%,#081f3d 100%)!important;min-height:100svh!important;width:100%!important;padding:26px 18px 32px!important;isolation:isolate}\nhtml body .page:before{inset:0!important;width:100%!important;height:100%!important;border-radius:0!important;transform:none!important;opacity:1!important;background:linear-gradient(125deg,transparent 20%,rgba(213,241,255,.14) 44%,transparent 64%)!important;filter:none!important;pointer-events:none}\nhtml body .page:after{display:none!important}\nhtml body .content{max-width:420px!important;margin:auto!important;gap:0!important}\nhtml body .name{font-size:clamp(25px,7vw,32px)!important;letter-spacing:-.7px!important;font-weight:750!important;text-shadow:0 2px 12px #0a244750!important;color:#fff!important}\nhtml body .desc,html body .bio{color:#e5f3ff!important;font-size:14px!important;line-height:1.5!important}\nhtml body .avatar-wrap{background:linear-gradient(145deg,#ffffff70,#c1eaff20)!important;border:1px solid #e8f7ff99!important;box-shadow:0 12px 30px #031b4740,inset 0 1px 2px #fff9!important;backdrop-filter:blur(18px)!important}\nhtml body .location{background:#c7e8ff20!important;border:1px solid #d8eeff50!important;color:#f0f8ff!important;box-shadow:inset 0 1px 1px #fff4,0 5px 12px #00193420!important}\nhtml body .links{display:grid!important;grid-template-columns:minmax(0,1fr)!important;gap:12px!important}\nhtml body .link-btn{position:relative!important;overflow:hidden!important;min-height:72px!important;border-radius:21px!important;padding:10px 13px!important;grid-template-columns:48px minmax(0,1fr) 18px!important;gap:10px!important;background:linear-gradient(145deg,rgba(235,249,255,.32),rgba(157,205,239,.14) 52%,rgba(207,235,255,.24))!important;color:#f5fbff!important;border:1px solid rgba(222,242,255,.55)!important;box-shadow:0 9px 23px #00172e40,inset 0 1px 1px #ffffff80,inset 0 -1px 2px #b8ddfa25!important;backdrop-filter:blur(18px) saturate(125%)!important;-webkit-backdrop-filter:blur(18px) saturate(125%)!important;text-shadow:none!important}\nhtml body .link-btn:before{content:\"\";position:absolute;inset:0;pointer-events:none;background:linear-gradient(112deg,#ffffff1c,transparent 44%);border-radius:inherit}\nhtml body .link-icon{width:44px!important;height:44px!important;border-radius:13px!important;background:linear-gradient(145deg,#f0f9ff60,#b5e0ff16)!important;border:1px solid #d9f0ff66!important;box-shadow:inset 0 1px 1px #fff7,0 3px 9px #001d492a!important;color:#fff!important}\nhtml body .link-icon img{object-fit:contain!important;padding:3px!important}\nhtml body .link-title{font-size:16px!important;font-weight:750!important;letter-spacing:-.15px!important}\nhtml body .link-sub{color:#d5e9fb!important;font-size:12px!important;font-weight:500!important;opacity:1!important;line-height:1.3!important}\nhtml body .footer{color:#c1d7ed!important}\n</style>" + "</head>", 1)

# Compact mobile viewport with layered refractive glass relief; never clip extra links or video.
TEMPLATES["instagram_card.html"] = TEMPLATES["instagram_card.html"].replace("</head>", "<style id=\"card-liquid-depth\">\nhtml body .page{padding:clamp(9px,1.8svh,17px) 15px!important;min-height:100svh!important;overflow:visible!important}\nhtml body .content{min-height:calc(100svh - clamp(18px,3.6svh,34px))!important;max-width:420px!important;justify-content:center!important}\nhtml body .top-logo{height:clamp(25px,4.8svh,40px)!important;margin:0 auto 4px!important}\nhtml body .top-logo img{max-height:100%!important;max-width:130px!important}\nhtml body .avatar-wrap{width:clamp(62px,11svh,96px)!important;height:clamp(62px,11svh,96px)!important;margin:4px auto 7px!important;padding:4px!important;background:linear-gradient(150deg,#ffffffb0,#b6dfff25 45%,#81b5e945 65%,#e6f7ffad)!important;border:1px solid #f3fbffb0!important;box-shadow:inset 0 3px 3px #ffffffbc,inset 0 -4px 5px #03396e65,0 6px 15px #001b4055!important}\nhtml body .name{font-size:clamp(21px,3.6svh,28px)!important;line-height:1.1!important;margin:0!important}\nhtml body .desc{font-size:clamp(11px,1.75svh,13px)!important;margin:3px 0!important;line-height:1.2!important}\nhtml body .bio{font-size:clamp(11px,1.7svh,13px)!important;line-height:1.3!important;margin:5px auto!important;max-width:350px!important}\nhtml body .location{font-size:11px!important;padding:5px 10px!important;margin:4px auto 9px!important;min-height:25px!important}\nhtml body .links{gap:clamp(5px,1svh,9px)!important;margin:0!important}\nhtml body .link-btn{min-height:clamp(43px,7.3svh,60px)!important;padding:5px 11px!important;border-radius:17px!important;grid-template-columns:36px minmax(0,1fr) 14px!important;gap:9px!important;background:linear-gradient(180deg,rgba(238,250,255,.37),rgba(177,221,255,.13) 28%,rgba(100,173,230,.18) 73%,rgba(207,238,255,.30))!important;border:1px solid #dcf4ff99!important;box-shadow:inset 0 2px 2px #ffffffbf,inset 2px 0 3px #e1f6ff55,inset -2px 0 4px #07345d45,inset 0 -3px 3px #041e4d65,0 5px 0 #071e3d33,0 8px 13px #031a3650!important;backdrop-filter:blur(16px) saturate(145%)!important}\nhtml body .link-btn:before{inset:2px 5px auto!important;height:40%!important;border-radius:14px 14px 40% 40%!important;background:linear-gradient(180deg,#ffffff40,transparent)!important}\nhtml body .link-icon{width:35px!important;height:35px!important;border-radius:11px!important;background:linear-gradient(145deg,#effaff90,#87bce952 50%,#d4efff80)!important;border:1px solid #ffffff88!important;box-shadow:inset 0 2px 2px #ffffffb0,inset 0 -3px 3px #123d7355,0 3px 5px #00172e66!important}\nhtml body .link-title{font-size:clamp(13px,2.2svh,16px)!important;line-height:1.1!important}\nhtml body .link-sub{font-size:clamp(10px,1.5svh,11px)!important;line-height:1.15!important;margin-top:2px!important}\nhtml body .footer{margin:0!important;padding-top:clamp(6px,1.3svh,12px)!important;font-size:10px!important}\nhtml body .link-btn:active{transform:translateY(2px)!important;box-shadow:inset 0 2px 5px #00172e55!important}\n@media(max-height:650px){html body .page{padding:7px 12px!important}html body .avatar-wrap{width:58px!important;height:58px!important}html body .top-logo{height:25px!important}html body .links{gap:5px!important}html body .link-btn{min-height:43px!important}html body .bio{margin:3px auto!important}html body .location{margin-bottom:6px!important}}\n</style>" + "</head>", 1)

